# Two-neuron spiking chain
def lif_step(v, I, tau=20.0, dt=1.0, th=1.0):
    v += dt*(-v/tau + I/tau)
    return (0.0, True) if v >= th else (v, False)
v1 = v2 = 0.0
for t in range(60):
    v1, s1 = lif_step(v1, 2.0 if t < 30 else 0.0)
    v2, s2 = lif_step(v2, 3.0 if s1 else 0.0)
    if s1 or s2:
        print(f"t={t:3d}  neuron1={'SPIKE' if s1 else ' . '}  neuron2={'SPIKE' if s2 else ' . '}")
